# ---------- PANEL C: punctuations, on the published specification ------------
# REBUILT 6 Aug 2026 to follow Jennings & John, "Punctuations and Turning Points in
# British Politics: the Policy Agenda of the Queen's Speech, 1940-2005", BJPS 40:
#   "change scores are equal to the percentage change in the percentage share of the
#    Queen's Speech for each year for each topic in turn ... cases where policy-making
#    attention remains stable at zero are treated as missing"
# and their Figure 6, which plots the kurtosis of the ANNUAL distribution.
#
# The previous version used raw differences in shares over an 11-year rolling window.
# That is not the published measure and it mattered: raw differences are bounded by
# the share itself, so as the agenda spreads across more topics the differences shrink
# mechanically. The measure was therefore partly tracking concentration — which is why
# it correlated with ENI at -0.42 and appeared to trend downward. On the published
# measure the trend disappears (p = 0.93) and the correlation with ENI falls to -0.05.
kurt_fn <- function(x){
  n<-length(x); m<-mean(x)
  (sum((x-m)^4)/n) / (sum((x-m)^2)/n)^2
}
# full topic x year grid so absent topics are explicit zeros, as in the paper
all_codes <- sort(unique(gov_shares$code)); all_yrs <- sort(unique(gov_shares$year))
grid <- expand_grid(year=all_yrs, code=all_codes) %>%
  left_join(gov_shares, by=c("year","code")) %>%
  mutate(pct = 100*replace_na(share, 0)) %>% select(year, code, pct)

pct_changes <- grid %>% arrange(code, year) %>% group_by(code) %>%
  mutate(prev = lag(pct)) %>% ungroup() %>% filter(!is.na(prev)) %>%
  filter(!(pct==0 & prev==0)) %>%                 # "stable at zero" -> missing
  filter(prev > 0) %>%                            # percentage change undefined from a zero base
  mutate(pct_change = 100*(pct-prev)/prev)

overall_kurt <- kurt_fn(pct_changes$pct_change)
n_total <- nrow(pct_changes)

ann_kurt <- pct_changes %>% group_by(year) %>% filter(n() >= 8) %>%
  summarise(kurtosis = kurt_fn(pct_change), n = n(), .groups="drop")

p_b <- ggplot(ann_kurt, aes(year, kurtosis)) +
  geom_hline(yintercept=3, linetype="dashed", colour="#888888", linewidth=0.5) +
  geom_line(colour="#000000", linewidth=0.6) +
