# ---------- PANEL D: Chow F-sweep on the government ENI ----------
# Computed on 1979-2026 — the displayed window. See the WINDOW RULE note at the top.
chow_res <- chow_sweep(year=gov_eni$year, y=gov_eni$eni)
curve_disp <- chow_res$curve
# ---- break-date uncertainty -------------------------------------------------
# The sweep's peak is NOT a dated break: F clears the 5% line at every candidate
# year, which indicates gradual change rather than a locatable break. Following the
# house method in break_sensitivity/break_ci_shape.R (moving-block bootstrap, L=4,
# B=3000, seed 42), the 90% CI for the break year spans essentially the whole
# admissible window. The asymptotic Bai CI is far narrower [1991,1994] but assumes a
# well-identified single break, so it is over-confident here. Panel D therefore shows
# the interval, not a year. diagnostics/eni_break_ci.R reproduces both.
rss_lin <- function(y){ m <- length(y); if(m < 3) return(0)
  x <- seq_len(m); xm <- mean(x); ym <- mean(y)
  syy <- sum((y-ym)^2); syy - sum((x-xm)*(y-ym))^2/sum((x-xm)^2) }
peak_year_of <- function(yr, v, trim=0.15){
  m <- length(v); a <- max(2, floor(trim*m)); b <- m-a
  pool <- rss_lin(v); Fs <- rep(NA_real_, m)
  for(k in a:b){ r <- rss_lin(v[1:k]) + rss_lin(v[(k+1):m]); Fs[k] <- ((pool-r)/2)/(r/(m-4)) }
  yr[which.max(Fs)] }
set.seed(42)
.v <- gov_eni$eni; .yr <- gov_eni$year; .n <- length(.v); .dv <- diff(.v); L <- 4; B <- 3000
boot_pk <- vapply(seq_len(B), function(b){
  nb <- ceiling((.n-1)/L); st <- sample(1:(length(.dv)-L+1), nb, replace=TRUE)
  peak_year_of(.yr, cumsum(c(.v[1], unlist(lapply(st, function(s) .dv[s:(s+L-1)]))[1:(.n-1)])))
}, numeric(1))
ci90 <- unname(quantile(boot_pk, c(.05,.95)))
plateau_yrs <- curve_disp %>% filter(F >= 0.85*chow_res$peak_F)

CI_PAD <- max(curve_disp$F)*0.22; CI_Y <- -CI_PAD*0.55; CI_T <- CI_PAD*0.12
p_c <- ggplot(curve_disp, aes(year, F)) +
  geom_hline(yintercept=chow_res$crit_5pct, linetype="dashed", colour="#888888", linewidth=0.5) +
  geom_line(colour="#000000", linewidth=0.6) +
  # 90% bootstrap interval for the break year, drawn at the foot of the panel.
  # No single year is marked: the interval spans almost the whole admissible window.
  annotate("segment", x=ci90[1], xend=ci90[2], y=CI_Y, yend=CI_Y,
           colour="#000000", linewidth=0.8) +
  annotate("segment", x=ci90[1], xend=ci90[1], y=CI_Y-CI_T, yend=CI_Y+CI_T, colour="#000000", linewidth=0.8) +
  annotate("segment", x=ci90[2], xend=ci90[2], y=CI_Y-CI_T, yend=CI_Y+CI_T, colour="#000000", linewidth=0.8) +
  annotate("text", x=(ci90[1]+ci90[2])/2, y=CI_Y, label="90% interval for the break year",
           colour="#000000", size=2.5, vjust=-0.9) +
  annotate("text", x=START, y=chow_res$crit_5pct, label="5% critical value",
           colour="#888888", size=2.5, hjust=0, vjust=-0.5) +
  scale_x_continuous(breaks=seq(1980,END,10)) +
  # y-range forced to include the critical line, which previously sat below the panel
  coord_cartesian(xlim=c(START, END+LABELPAD),
                  ylim=c(-CI_PAD, max(curve_disp$F, chow_res$crit_5pct)*1.12)) +
  labs(x=NULL, y=sprintf("Chow F(2,%d)", chow_res$n-4),
       tag="D",
       subtitle="F-statistic for a break at each candidate year, with the 90% bootstrap interval for the break year") +
  theme_minimal(base_size=10) +
  theme(panel.grid.minor=element_blank(), panel.grid.major.x=element_blank(),
        plot.tag=element_text(size=11, face="bold"),
        plot.subtitle=element_text(size=9, face="italic", colour="grey30"))

